function validate([nums, k]) {
  if (!Number.isInteger(k) || k < 1) return 'k must be a positive integer.';
  if (nums.length < k || nums.length > 100000) return 'nums needs at least k and at most 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is an integer from 1 to 10^9.';
  return null;
}

