function isPossibleDivide(nums, k) {
  if (nums.length % k !== 0) {
    return false;
  }
  const count = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) ?? 0) + 1);
  }
  const keys = [...count.keys()].sort((a, b) => a - b);
  for (const start of keys) {
    const need = count.get(start);
    if (need === 0) {
      continue;
    }
    for (let value = start; value < start + k; value++) {
      const have = count.get(value) ?? 0;
      if (have < need) {
        return false;
      }
      count.set(value, have - need);
    }
  }
  return true;
}

