function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const k = large ? pick(1, 40) : pick(1, 4);
  const base = rand() < 0.2 ? 1000000000 - (large ? 3000 : 20) : 1;
  const spread = large ? pick(k, 3 * k + 200) : pick(k, k + 5);
  const nums = [];
  if (rand() < 0.25 && !large) {
    const n = pick(Math.max(1, k), 9);
    for (let i = 0; i < n; i++) nums.push(base + pick(0, spread));
  } else {
    const groups = large ? Math.floor(2000 / k) : pick(1, Math.max(1, Math.floor(9 / k)));
    for (let g = 0; g < groups; g++) {
      const start = base + pick(0, spread);
      for (let i = 0; i < k; i++) nums.push(start + i);
    }
    const roll = rand();
    if (roll < 0.25) nums[pick(0, nums.length - 1)] = base + pick(0, spread + k);
    else if (roll < 0.35 && nums.length > k) nums.pop();
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums, k];
}
